/// One finished session, reduced to what the clock says.
class SessionDuration {
  const SessionDuration({
    required this.date,
    required this.dayId,
    required this.actualMinutes,
    required this.estimatedMinutes,
  });

  final DateTime date;
  final String dayId;
  final int actualMinutes;

  /// What `day.estMinutes` promised. Generated by `tools/gen.py` from the
  /// prescriptions, never typed by hand.
  final int estimatedMinutes;

  int get overrunMinutes => actualMinutes - estimatedMinutes;
  bool get overran => actualMinutes > estimatedMinutes;
}

/// Is half an hour real, or is it fifty minutes?
///
/// The programme is built around a working student's half hour, with a hard
/// 35-minute ceiling (V11). If the sessions actually take fifty, the answer
/// is to cut volume — not to quietly raise the estimate, which is how a
/// training plan stops being a plan.
class SessionStats {
  const SessionStats(this.durations);

  final List<SessionDuration> durations;

  static const int ceilingMinutes = 35;

  bool get isEmpty => durations.isEmpty;

  int get count => durations.length;

  /// The median, not the mean: one session where you took a phone call in the
  /// middle should not move the number everything else is judged against.
  int get medianMinutes {
    if (durations.isEmpty) return 0;
    final sorted = [for (final d in durations) d.actualMinutes]..sort();
    final mid = sorted.length ~/ 2;
    return sorted.length.isOdd
        ? sorted[mid]
        : ((sorted[mid - 1] + sorted[mid]) / 2).round();
  }

  int get longestMinutes => durations.isEmpty
      ? 0
      : durations.map((d) => d.actualMinutes).reduce((a, b) => a > b ? a : b);

  int get overCeilingCount =>
      durations.where((d) => d.actualMinutes > ceilingMinutes).length;

  /// Typical difference between what was promised and what it took.
  int get medianOverrunMinutes {
    if (durations.isEmpty) return 0;
    final sorted = [for (final d in durations) d.overrunMinutes]..sort();
    final mid = sorted.length ~/ 2;
    return sorted.length.isOdd
        ? sorted[mid]
        : ((sorted[mid - 1] + sorted[mid]) / 2).round();
  }

  /// True when the ceiling is fiction and the programme needs less in it.
  ///
  /// One long session is life; a majority of them means the sessions are too
  /// big for the hour they have.
  bool get ceilingIsFiction =>
      durations.length >= 4 && overCeilingCount * 2 > durations.length;

  String get verdict {
    if (isEmpty) return 'No finished sessions yet.';
    if (ceilingIsFiction) {
      return 'Median $medianMinutes min across $count sessions — '
          '$overCeilingCount ran past $ceilingMinutes minutes. The sessions are '
          'too big for the time they have; cut volume rather than moving the '
          'ceiling.';
    }
    if (medianMinutes > ceilingMinutes) {
      return 'Median $medianMinutes min. Close to the line, worth watching.';
    }
    return 'Median $medianMinutes min across $count sessions. The half hour '
        'holds.';
  }
}
